import express from 'express';
import mongoose from 'mongoose';
import TripRequest from '../models/TripRequest.js';
import Itinerary from '../models/Itinerary.js';
import Booking from '../models/Booking.js';
import User from '../models/User.js';
import Review from '../models/Review.js';
import requireAuth from '../middleware/requireAuth.js';
import requireAdmin from '../middleware/requireAdmin.js';

const router = express.Router();

/**
 * GET /api/analytics/me
 * Flow:
 *   requireAuth
 *   -> count itineraries generated by this user
 *   -> sum booking spend
 *   -> most visited destinations (by their own itineraries)
 *   -> average rating given by user (from Review)
 *   -> return personal stats object
 */
router.get('/me', requireAuth, async (req, res) => {
  try {
    const userId = req.user.id;

    const [tripsGenerated, totalSpend, topDestinations, reviewsGiven] =
      await Promise.all([
        Itinerary.countDocuments({ userId }),
        Booking.aggregate([
          { $match: { userId: new mongoose.Types.ObjectId(userId) } },
          { $group: { _id: null, total: { $sum: '$totalAmount' } } },
        ]),
        Itinerary.aggregate([
          { $match: { userId: new mongoose.Types.ObjectId(userId) } },
          {
            $group: {
              _id: { $first: '$destinations' },
              count: { $sum: 1 },
            },
          },
          { $sort: { count: -1 } },
          { $limit: 5 },
        ]),
        Review.countDocuments({ user: userId }),
      ]);

    return res.json({
      tripsGenerated,
      totalSpend: totalSpend[0]?.total || 0,
      topDestinations: topDestinations.map((d) => ({
        destination: d._id,
        trips: d.count,
      })),
      reviewsGiven,
    });
  } catch (err) {
    console.error('GET /analytics/me error:', err);
    return res.status(500).json({ error: 'Failed to fetch your stats' });
  }
});

/**
 * GET /api/analytics/admin/overview
 * Flow:
 *   requireAuth -> requireAdmin
 *   -> total users, total trip requests, total itineraries, total bookings
 *   -> revenue sum from bookings
 *   -> signups in last 30 days (growth trend)
 *   -> return summary
 */
router.get('/admin/overview', requireAuth, requireAdmin, async (req, res) => {
  try {
    const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

    const [
      totalUsers,
      totalTripRequests,
      totalItineraries,
      totalBookings,
      revenueAgg,
      newUsersLast30Days,
      generatedVsFailed,
    ] = await Promise.all([
      User.countDocuments(),
      TripRequest.countDocuments(),
      Itinerary.countDocuments(),
      Booking.countDocuments(),
      Booking.aggregate([
        { $group: { _id: null, total: { $sum: '$totalAmount' } } },
      ]),
      User.countDocuments({ createdAt: { $gte: thirtyDaysAgo } }),
      Itinerary.aggregate([
        { $group: { _id: '$status', count: { $sum: 1 } } },
      ]),
    ]);

    return res.json({
      totalUsers,
      totalTripRequests,
      totalItineraries,
      totalBookings,
      totalRevenue: revenueAgg[0]?.total || 0,
      newUsersLast30Days,
      itinerariesByStatus: generatedVsFailed.reduce((acc, s) => {
        acc[s._id] = s.count;
        return acc;
      }, {}),
    });
  } catch (err) {
    console.error('GET /analytics/admin/overview error:', err);
    return res.status(500).json({ error: 'Failed to fetch admin overview' });
  }
});

/**
 * GET /api/analytics/admin/popular-destinations?limit=10
 * Flow:
 *   requireAuth -> requireAdmin
 *   -> group itineraries by destination
 *   -> sort by count desc
 *   -> return top N
 */
router.get('/admin/popular-destinations', requireAuth, requireAdmin, async (req, res) => {
  try {
    const limit = Math.min(parseInt(req.query.limit) || 10, 50);
    const destinations = await Itinerary.aggregate([
      { $group: { _id: { $first: '$destinations' }, count: { $sum: 1 } } },
      { $sort: { count: -1 } },
      { $limit: limit },
    ]);
    return res.json({
      destinations: destinations.map((d) => ({
        destination: d._id,
        trips: d.count,
      })),
    });
  } catch (err) {
    console.error('GET /analytics/admin/popular-destinations error:', err);
    return res.status(500).json({ error: 'Failed to fetch popular destinations' });
  }
});

/**
 * GET /api/analytics/admin/spending-patterns
 * Flow:
 *   requireAuth -> requireAdmin
 *   -> average booking amount
 *   -> spend bucketed by month (last 12 months)
 *   -> spend by destination
 */
router.get('/admin/spending-patterns', requireAuth, requireAdmin, async (req, res) => {
  try {
    const twelveMonthsAgo = new Date();
    twelveMonthsAgo.setMonth(twelveMonthsAgo.getMonth() - 12);

    const [avgAgg, monthlySpend, spendByDestination] = await Promise.all([
      Booking.aggregate([
        { $group: { _id: null, avg: { $avg: '$totalAmount' } } },
      ]),
      Booking.aggregate([
        { $match: { createdAt: { $gte: twelveMonthsAgo } } },
        {
          $group: {
            _id: { year: { $year: '$createdAt' }, month: { $month: '$createdAt' } },
            total: { $sum: '$totalAmount' },
            count: { $sum: 1 },
          },
        },
        { $sort: { '_id.year': 1, '_id.month': 1 } },
      ]),
      Booking.aggregate([
        {
          $lookup: {
            from: 'itineraries',
            localField: 'itineraryId',
            foreignField: '_id',
            as: 'itinerary',
          },
        },
        { $unwind: '$itinerary' },
        {
          $group: {
            _id: { $first: '$itinerary.destinations' },
            total: { $sum: '$totalAmount' },
          },
        },
        { $sort: { total: -1 } },
        { $limit: 10 },
      ]),
    ]);

    return res.json({
      averageBookingAmount: avgAgg[0]?.avg || 0,
      monthlySpend: monthlySpend.map((m) => ({
        year: m._id.year,
        month: m._id.month,
        total: m.total,
        bookings: m.count,
      })),
      spendByDestination: spendByDestination.map((s) => ({
        destination: s._id,
        total: s.total,
      })),
    });
  } catch (err) {
    console.error('GET /analytics/admin/spending-patterns error:', err);
    return res.status(500).json({ error: 'Failed to fetch spending patterns' });
  }
});

/**
 * GET /api/analytics/admin/funnel
 * Flow:
 *   requireAuth -> requireAdmin
 *   -> trip requests submitted vs itineraries generated vs saved vs booked
 *   -> gives a conversion funnel view for the admin dashboard
 */
router.get('/admin/funnel', requireAuth, requireAdmin, async (req, res) => {
  try {
    const [tripRequests, itinerariesGenerated, itinerariesSaved, bookings] =
      await Promise.all([
        TripRequest.countDocuments(),
        Itinerary.countDocuments({ status: 'generated' }),
        Itinerary.countDocuments({ status: 'saved' }),
        Booking.countDocuments(),
      ]);

    return res.json({
      funnel: [
        { stage: 'Trip Requests Submitted', count: tripRequests },
        { stage: 'Itineraries Generated', count: itinerariesGenerated },
        { stage: 'Itineraries Saved', count: itinerariesSaved },
        { stage: 'Bookings Made', count: bookings },
      ],
    });
  } catch (err) {
    console.error('GET /analytics/admin/funnel error:', err);
    return res.status(500).json({ error: 'Failed to fetch funnel data' });
  }
});

export default router;
